35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
43	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
44	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
45	import org.springframework.samples.petclinic.rest.validation.RegistrationDateNormalizer;
46	import org.springframework.samples.petclinic.rest.validation.RegistrationDateValidator;
47	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.servlet.http.HttpServletRequest;
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
73	    private final PetMapper petMapper;
74	
75	    private final VisitMapper visitMapper;
76	
77	    private final IdempotencyStore idempotencyStore;
78	
79	    private final HttpServletRequest request;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper,
85	                                 IdempotencyStore idempotencyStore,
86	                                 HttpServletRequest request) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	        this.idempotencyStore = idempotencyStore;
92	        this.request = request;
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
98	        Collection<Owner> owners;
99	        if (lastName != null) {
100	            owners = this.clinicService.findOwnerByLastName(lastName);
101	        } else {
102	            owners = this.clinicService.findAllOwners();
103	        }
104	        if (owners.isEmpty()) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
113	        Owner owner = this.clinicService.findOwnerById(ownerId);
114	        if (owner == null) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
123	        String idempotencyKey = request.getHeader("Idempotency-Key");
124	        ResponseEntity<OwnerDto> replayed = replayIdempotent(idempotencyKey);
125	        if (replayed != null) {
126	            return replayed;
127	        }
128	        HttpHeaders headers = new HttpHeaders();
129	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
130	        String telephone = TelephoneNormalizer.normalize(owner.getTelephone());
131	        owner.setTelephone(telephone);
132	        String email = EmailNormalizer.normalize(owner.getEmail());
133	        owner.setEmail(email);
134	        normalizeAddress(owner);
135	        PostcodeValidator.validate(owner.getPostcode(), owner.getCity());
136	        RegistrationDateValidator.validate(owner.getRegistrationDate());
137	        LocalDate effectiveRegistrationDate =
138	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
139	        owner.setRegistrationDate(RegistrationDateNormalizer.normalize(effectiveRegistrationDate));
140	        this.clinicService.createOwner(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
141	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
142	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
143	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
144	        idempotencyStore.remember(idempotencyKey, owner.getId());
145	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
146	        headers.setLocation(UriComponentsBuilder.newInstance()
147	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
148	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
149	    }
150	
151	    /**
152	     * When {@code idempotencyKey} names a create that already succeeded, return the originally
153	     * created owner with {@code 200 OK} so the repeat is not persisted as a duplicate. Returns
154	     * {@code null} when there is no key or none has been seen, so the caller proceeds with a
155	     * normal create.
156	     */
157	    private ResponseEntity<OwnerDto> replayIdempotent(String idempotencyKey) {
158	        return idempotencyStore.find(idempotencyKey)
