/**
 * Derives the owner's numeric membership level from {@link #membershipPoints(Owner)}: level
 * {@code 1} for {@code 0-1} points, level {@code 2} for {@code 2-3} points, level {@code 3}
 * for {@code 4-5} points, and level {@code 4} for {@code 6} or more points. The result is then
 * capped so it cannot exceed the owner's {@code membershipLevelCap} (one above the maximum
 * membership level among the household members present when the owner was created); a
 * {@code null} cap — set when the owner had no existing household member — leaves the level
 * uncapped.
 */
default Integer membershipLevel(Owner owner) {
    if (owner == null) {
        return null;
    }
    int points = membershipPoints(owner);
    int level;
    if (points <= 1) {
        level = 1;
    } else if (points <= 3) {
        level = 2;
    } else if (points <= 5) {
        level = 3;
    } else {
        level = 4;
    }
    Integer cap = owner.getMembershipLevelCap();
    if (cap != null && level > cap) {
        level = cap;
    }
    return level;
}

